Write pytest tests for a clock-based scheduler using a fixture that returns a fake clock object the tests can control.

class Scheduler:
    def __init__(self, clock):
        self.clock = clock
        self.scheduled = []
    def schedule(self, delay):
        self.scheduled.append(self.clock.now() + delay)

output:
import pytest
from scheduler import Scheduler

class FakeClock:
    def __init__(self, start=1000):
        self.value = start
    def now(self):
        return self.value
    def advance(self, seconds):
        self.value += seconds

@pytest.fixture
def clock():
    return FakeClock()

def test_schedule_uses_current_time(clock):
    scheduler = Scheduler(clock)
    scheduler.schedule(30)
    assert scheduler.scheduled == [1030]

def test_schedule_after_advance(clock):
    scheduler = Scheduler(clock)
    clock.advance(50)
    scheduler.schedule(10)
    assert scheduler.scheduled == [1060]

