Write pytest tests for a stack fixture used across multiple tests: push items in the fixture and verify pop/peek behavior, including empty-stack errors.

class Stack:
    def __init__(self):
        self.items = []
    def push(self, x):
        self.items.append(x)
    def pop(self):
        return self.items.pop()

output:
import pytest
from stack import Stack

@pytest.fixture
def stack():
    s = Stack()
    for v in [1, 2, 3]:
        s.push(v)
    return s

def test_pop_returns_last_pushed(stack):
    assert stack.pop() == 3

def test_peek_semantics_via_pop_order(stack):
    assert [stack.pop() for _ in range(3)] == [3, 2, 1]

def test_empty_stack_raises(stack):
    for _ in range(3):
        stack.pop()
    with pytest.raises(IndexError):
        stack.pop()

